let notificationsEnabled = false;

export function getNotificationPreference(): boolean {
  return notificationsEnabled;
}

export function setNotificationPreference(value: boolean): void {
  notificationsEnabled = value;
}

"use server";

import { revalidatePath } from "next/cache";
import { getNotificationPreference, setNotificationPreference } from "./data";

export async function toggleNotifications(): Promise<void> {
  const current = getNotificationPreference();
  setNotificationPreference(!current);
  revalidatePath("/");
}

