import { toggleNotifications } from "./actions";
import { getNotificationPreference } from "./data";

export default function Home() {
  const enabled = getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? "ON" : "OFF"}</p>
      <form action={toggleNotifications}>
        <button type="submit">{enabled ? "Turn off" : "Turn on"}</button>
      </form>
    </main>
  );
}

export const metadata = {
  title: "Settings",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

